pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(text) = bytes.strip_prefix("v:2|hello|") {
        return Ok(Msg::Hello(text.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat|") {
        return sequence
            .parse::<u32>()
            .map(Msg::Heartbeat)
            .map_err(|_| "invalid heartbeat sequence".into());
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(text) => format!("v:2|hello|{text}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat|{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_roundtrips_in_v2_envelope() {
        let msg = Msg::Hello("Ada|Lovelace".into());
        assert_eq!(encode(&msg), "v:2|hello|Ada|Lovelace");
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(text)) if text == "Ada|Lovelace"));
    }

    #[test]
    fn heartbeat_roundtrips_with_sequence_number() {
        let msg = Msg::Heartbeat(42);
        assert_eq!(encode(&msg), "v:2|heartbeat|42");
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
